insert into public.settings (key, value, updated_by) values
  ('calendar', '{"timezone": "Africa/Nairobi", "send_days": ["mon", "tue", "wed", "thu", "fri"], "holidays": [{"date": "2026-10-10", "name": "Utamaduni / Moi Day"}, {"date": "2026-10-20", "name": "Mashujaa Day"}, {"date": "2026-12-12", "name": "Jamhuri Day"}, {"date": "2026-12-25", "name": "Christmas Day"}, {"date": "2026-12-26", "name": "Boxing Day"}, {"date": "2027-01-01", "name": "New Year''s Day"}, {"date": "2027-03-26", "name": "Good Friday"}, {"date": "2027-03-29", "name": "Easter Monday"}, {"date": "2027-05-01", "name": "Labour Day"}, {"date": "2027-06-01", "name": "Madaraka Day"}, {"date": "2027-10-11", "name": "Utamaduni / Moi Day (observed)"}, {"date": "2027-10-20", "name": "Mashujaa Day"}, {"date": "2027-12-13", "name": "Jamhuri Day (observed)"}, {"date": "2027-12-27", "name": "Christmas Day (observed)"}], "pauses": [{"start": "2026-12-21", "end": "2027-01-01", "name": "December break"}], "pauses_block_followups": true, "followups": {"fu1_working_days": 3, "fu2_working_days": 8, "demo_fu_working_days": [1, 4]}, "pacing": {"max_per_hour": 15, "batch_windows": [{"start": "09:30", "end": "11:00"}, {"start": "14:00", "end": "15:30"}]}, "same_day_demo_cutoff": "17:00"}'::jsonb, 'seed'),
  ('subcategories', '{"property_agency": {"label": "Property agencies", "active": true, "template": "property_agency"}, "land_developers": {"label": "Land & developers", "active": true, "template": "land_developers"}, "construction": {"label": "Construction", "active": false, "template": "construction"}, "hardware_supplies": {"label": "Hardware & supplies", "active": false, "template": "hardware_supplies"}, "roofing_steel": {"label": "Roofing & steel", "active": false, "template": "roofing_steel"}}'::jsonb, 'seed'),
  ('scoring', '{"ads_min_score": 35.0}'::jsonb, 'seed'),
  ('pilot', '{"pilot_days": 7, "budget_kes": 5000, "vat_note": "about KES 4,300 goes to the ads; the rest is VAT that Meta charges", "split": {"test_days": [1, 2], "winner_days": [3, 7], "test_share": 0.45}, "stop_rule": {"max_cost_per_chat_kes": 250, "after_hours": 48}, "reply_rule": "reply within 15 minutes, 8am-8pm", "estimates": {"land_developers": {"reach": [25000, 60000], "chats": [30, 100], "serious": [5, 15], "visits": [1, 5]}, "property_agency": {"reach": [25000, 60000], "chats": [40, 120], "serious": [8, 20], "visits": [2, 8]}, "budget_multipliers": {"5000": 1.0, "10000": 1.8, "20000": 3.2}}, "pricing": {"engine_intro_kes": 10000, "engine_standard_kes": 15000, "website_setup_kes": 5000, "website_monthly_kes": 4000, "website_min_months": 12, "december_pack_kes": 12000}, "targeting": {"pilot": {"mode": "radius", "radius_km": 40, "country": "KE"}, "december_pack_countries": ["AE", "SA", "QA", "GB", "US"]}}'::jsonb, 'seed'),
  ('messaging', '{"signoff": "— Swalleh, Raswal Tech Solutions", "length": {"min": 380, "max": 700}}'::jsonb, 'seed'),
  ('budget', '{"places_calls_per_month": 900, "places_calls_per_night": 40, "psi_calls_per_night": 150, "gemini_calls_per_night": 60, "db_cap_mb": 400, "storage_cap_mb": 800}'::jsonb, 'seed'),
  ('quick_replies', '[{"key": "price", "label": "How much?", "text": "The pilot itself is free. You only fund the ads: KES 5,000 all-in, and it goes to Facebook, not to us. If you like the results, the Enquiry Engine is KES 10,000/month (introductory; standard KES 15,000) plus your ad budget: new ads every week, testing, targeting, WhatsApp setup and a weekly report.", "action": null}, {"key": "how_5k", "label": "How is the 5k used?", "text": "From your KES 5,000, about KES 4,300 goes to the ads; the rest is VAT that Meta charges. Days 1–2 we test 3 ads; days 3–7 we put the money behind the winner. You get a short WhatsApp update every day.", "action": null}, {"key": "results", "label": "What results?", "text": "Honest answer: we promise enquiries, not sales. From KES 5,000 we''d expect roughly 30–120 WhatsApp chats and a few site visits booked, depending on your offer. We agree targets with you before we start.", "action": null}, {"key": "safe", "label": "Is it safe?", "text": "Your Page, your WhatsApp and your buyers stay yours. We only get permission to advertise on your Page, with no passwords, and you can remove us any time in one tap.", "action": null}, {"key": "no_page", "label": "No Facebook Page", "text": "No problem. We''ll create your Facebook Page together on a 10-minute call, on your phone, so it''s fully yours.", "action": null}, {"key": "start_pilot", "label": "Start the pilot", "text": "Karibu! 🙏 To set up your pilot, please send: (1) the project or plots to advertise and the exact location, (2) plot size and price, cash and instalment, (3) deposit and number of months, (4) title status, be honest, we only say ready title if it is, (5) site-visit days and pickup point, (6) 5–10 photos or short videos (drone clips are gold).", "action": null}, {"key": "website", "label": "Websites?", "text": "Websites are KES 5,000 setup + KES 4,000/month (12-month plan): hosting, updates and a WhatsApp button included.", "action": null}, {"key": "december", "label": "December pack", "text": "For December we have a Diaspora pack: KES 12,000 one-off. We create December ads aimed at Kenyans abroad who are planning to buy at home, and run them for you. Ad budget is separate.", "action": null}, {"key": "who", "label": "Who is this?", "text": "I''m Swalleh from Raswal Tech Solutions in Nairobi. We run Facebook and Instagram ads that send buyer enquiries straight to WhatsApp. I found {business} on Google Maps; your number is on the listing. If you''d prefer I don''t message again, just say so.", "action": null}, {"key": "has_provider", "label": "We already have someone", "text": "Great, glad you''re covered! Keep the mockup, and all the best. If you ever want a second opinion on your ads, I''m here.", "action": "lost_has_provider"}, {"key": "not_now", "label": "Not now", "text": "No problem at all. December is a busy month for buyers coming home. Shall I check back with you early December?", "action": "snooze"}, {"key": "stop", "label": "Stop / not interested", "text": "Sorry for the bother, I won''t message again. Asante.", "action": "opt_out"}, {"key": "holding", "label": "Plan tomorrow (over cap)", "text": "Asante! I''ll have your plan ready by tomorrow morning.", "action": null}]'::jsonb, 'seed'),
  ('followup_templates', '{"fu1": "Habari {business} team, just checking you saw the ad mockup I sent on {weekday}? The free 7-day pilot is still open. I can share the full plan: your 3 ads, who they''ll reach and exactly how the KES 5,000 is used. Asante. — Swalleh", "fu2": "Habari {business} team, a last note from me. If ads aren''t a priority right now, no problem at all; the mockup is yours to keep. Whenever you''d like the full plan, just reply \"plan\". Asante, and all the best with sales. — Swalleh", "plan_delivery": "Habari {business} team 👋 Here''s your 7-day enquiry pilot plan: your 3 ads, who will see them, and how the KES 5,000 is used: {link} It''s best on your phone, just scroll. Asante! — Swalleh, Raswal Tech Solutions", "demo_fu1": "Habari {business} team, did you get a chance to scroll through your pilot plan? Happy to adjust anything: the ads, the areas or the budget. — Swalleh", "demo_fu2": "Habari {business} team, shall we start your free 7-day pilot this week? Once we have a few details and the KES 5,000, your ads can be live within 24 hours. — Swalleh"}'::jsonb, 'seed'),
  ('demo_cap', '{"pilot": 5}'::jsonb, 'seed'),
  ('daily_mix', '{"land_developers": 20, "property_agency": 10}'::jsonb, 'seed'),
  ('outreach_whatsapp', '""'::jsonb, 'seed'),
  ('pause_list', '[]'::jsonb, 'seed')
